package pt.contracts.daily;

import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import pt.contracts.daily.DailyRules.*;
import pt.contracts.daily.DailyLedger.*;

class DailyLedgerTest {
    private static final long NOW=1_792_497_600_000L;
    private static final UUID PLAYER=new UUID(10,11),OTHER=new UUID(10,12);
    private List<Template> catalog(){try(var paths=Files.list(Path.of("src/main/resources/data/contracts/daily_quest"))){return paths.sorted().map(p->{try{return DailyLedger.JSON.fromJson(Files.readString(p),Template.class);}catch(Exception e){throw new IllegalStateException(e);}}).toList();}catch(Exception e){throw new IllegalStateException(e);}}
    private DailyLedger ledger(){DailyLedger l=new DailyLedger();l.salt=new UUID(88,99);return l;}
    private Round round(DailyLedger l){return l.generate(PLAYER,NOW,catalog(),"CHRONICLES");}
    private Reward complete(DailyLedger l,Quest q,int publicRep){l.accept(PLAYER,q.id,NOW+1);assertTrue(l.progress(PLAYER,q.id,q.template.quantity(),NOW+2));return l.complete(PLAYER,q.id,NOW+3,1000,publicRep,3);}
    @Test void realCatalogueGeneratesTwoEasyTwoMediumAndOneHardWithoutDuplicateObjectives(){var l=ledger();var r=round(l);assertEquals(5,r.quests.size());assertEquals(2,r.quests.stream().filter(q->q.template.difficulty()==Difficulty.EASY).count());assertEquals(2,r.quests.stream().filter(q->q.template.difficulty()==Difficulty.MEDIUM).count());assertEquals(1,r.quests.stream().filter(q->q.template.difficulty()==Difficulty.HARD).count());assertEquals(5,r.quests.stream().map(q->q.template.objectiveKey()).distinct().count());assertEquals(5,r.quests.stream().map(q->q.template.category()).distinct().count());}
    @Test void rewardRangesAndCapHoldAcrossAThousandPlayerDays(){var l=ledger();l.settings.bonuses.replaceAll((c,v)->2000);l.settings.allBonus=1000;var templates=catalog();for(int i=0;i<1000;i++){UUID player=new UUID(50,i);Round r=l.generate(player,NOW,templates,"CHRONICLES");long total=r.allBonus;for(var q:r.quests){Range range=l.settings.range(q.template.difficulty());assertTrue(q.base>=range.minimum()&&q.base<=range.maximum());assertTrue(q.bonus>=0&&q.bonus<=q.base/5);total+=q.gross;}assertTrue(total<=30000);}}
    @Test void samePlayerCannotRerollByRejoiningOrRequestingAnotherGeneration(){var l=ledger();var first=round(l);String before=DailyLedger.JSON.toJson(first);assertSame(first,l.generate(PLAYER,NOW+10000,catalog(),"CHRONICLES"));assertEquals(before,DailyLedger.JSON.toJson(first));}
    @Test void playerSetsHaveIndependentIdsAndProgress(){var l=ledger();var a=round(l);var b=l.generate(OTHER,NOW,catalog(),"CHRONICLES");assertTrue(Collections.disjoint(a.quests.stream().map(q->q.id).toList(),b.quests.stream().map(q->q.id).toList()));l.accept(PLAYER,a.quests.getFirst().id,NOW+1);assertTrue(b.quests.stream().allMatch(q->q.state==State.AVAILABLE));}
    @Test void progressBeforeAcceptanceDoesNotCount(){var l=ledger();var q=round(l).quests.getFirst();assertFalse(l.progress(PLAYER,q.id,999,NOW));assertEquals(0,q.progress);assertThrows(IllegalStateException.class,()->l.complete(PLAYER,q.id,NOW,0,0,3));}
    @Test void multipleQuestsCanBeAcceptedAndCompletedInAnyOrder(){var l=ledger();var r=round(l);r.quests.forEach(q->l.accept(PLAYER,q.id,NOW+1));for(int i=4;i>=0;i--){Quest q=r.quests.get(i);l.progress(PLAYER,q.id,q.template.quantity(),NOW+2);l.complete(PLAYER,q.id,NOW+3,0,0,3);}assertEquals(5,l.rewards.size());assertTrue(r.quests.stream().allMatch(q->q.state==State.PENDING));}
    @Test void incompleteQuestsExpireAtTheirStoredUtcBoundary(){var l=ledger();var old=round(l);var q=old.quests.getFirst();l.accept(PLAYER,q.id,NOW+1);l.progress(PLAYER,q.id,1,NOW+2);var next=l.generate(PLAYER,old.resetAt,catalog(),"CHRONICLES");assertEquals(State.EXPIRED,q.state);assertNotSame(old,next);assertTrue(next.quests.stream().allMatch(v->v.progress==0));assertThrows(IllegalArgumentException.class,()->l.quest(PLAYER,q.id));}
    @Test void movingTheClockBackCannotRegenerateOrUndoPaidRewards(){var l=ledger();var first=round(l);var reward=complete(l,first.quests.getFirst(),0);l.paid(reward.id);Round tomorrow=l.generate(PLAYER,first.resetAt,catalog(),"CHRONICLES");assertSame(tomorrow,l.generate(PLAYER,NOW-2*DailyRules.DAY,catalog(),"CHRONICLES"));assertTrue(l.rewards.get(reward.id).paid);}
    @Test void changedResetHourCannotRerollTheCurrentRound(){var l=ledger();Round r=round(l);l.settings.resetMinute=360;assertSame(r,l.generate(PLAYER,NOW+3600000,catalog(),"CHRONICLES"));assertEquals(r.resetAt,l.account(PLAYER).round.resetAt);}
    @Test void configurableResetMinuteUsesRealUtcDays(){Settings s=new Settings();s.resetMinute=360;long morning=java.time.Instant.parse("2026-10-20T05:59:59Z").toEpochMilli();assertEquals(java.time.Instant.parse("2026-10-20T06:00:00Z").toEpochMilli(),s.nextReset(morning));assertEquals(s.day(morning)+1,s.day(morning+1000));}
    @Test void generationSnapshotsMoneyBonusAndReputation(){var l=ledger();Round r=round(l);String before=DailyLedger.JSON.toJson(r);l.settings.easyMin=1200;l.settings.easyMax=3000;l.settings.bonuses.replaceAll((c,v)->2000);l.settings.hardReputation=20;assertEquals(before,DailyLedger.JSON.toJson(r));}
    @Test void sameCompletionCannotMintASecondReceipt(){var l=ledger();Quest q=round(l).quests.getFirst();Reward r=complete(l,q,0);assertEquals(r.gross,r.net+r.tax);assertThrows(IllegalStateException.class,()->l.complete(PLAYER,q.id,NOW+4,1000,0,3));assertEquals(1,l.rewards.size());assertFalse(l.progress(PLAYER,q.id,1,NOW+4));}
    @Test void paymentReplayDoesNotAddToDailyTotals(){var l=ledger();Round day=round(l);Reward r=complete(l,day.quests.getFirst(),0);l.paid(r.id);long total=day.grossPaid;l.paid(r.id);assertEquals(total,day.grossPaid);assertEquals(State.PAID,day.quests.getFirst().state);}
    @Test void taxRoundingConservesEveryCent(){assertEquals(0,DailyRules.tax(1000,500,"EMERALD"));assertEquals(50,DailyRules.tax(1000,500,"CHRONICLES"));assertEquals(200,DailyRules.tax(1000,2500,"EMERALD"));for(int bps:new int[]{0,1,333,1000,2500,10000})for(long amount:new long[]{1,99,100,10001,12000}){long tax=DailyRules.tax(amount,bps);assertEquals(amount,amount-tax+tax);assertEquals(amount*bps/10000,tax);}}
    @Test void reputationalCeilingIncludesPublicContractAwards(){var l=ledger();Round r=round(l);int rep=0;for(Quest q:r.quests)rep+=complete(l,q,2).reputation;assertEquals(1,rep);assertEquals(1,l.reputation(PLAYER,NOW));}
    @Test void specialCelebrationWaitsForFiveConfirmedPaymentsAndOccursOnce(){var l=ledger();Round r=round(l);for(int i=0;i<5;i++){Reward paid=complete(l,r.quests.get(i),0);assertNull(l.special(PLAYER,NOW+5,1000));l.paid(paid.id);}Reward finale=l.special(PLAYER,NOW+5,1000);assertNotNull(finale);assertEquals(0,finale.gross);assertEquals(Difficulty.ALL,finale.difficulty);assertNull(l.special(PLAYER,NOW+6,1000));l.paid(finale.id);l.validate();}
    @Test void optionalAllCompleteBonusIsReservedInsideTheGenerationCap(){var l=ledger();l.settings.allBonus=1500;l.settings.bonuses.replaceAll((c,v)->2000);Round r=round(l);for(var q:r.quests)l.paid(complete(l,q,0).id);Reward bonus=l.special(PLAYER,NOW+5,2500);assertEquals(1500,bonus.gross);assertTrue(r.grossCompleted<=r.cap);assertEquals(bonus.gross,bonus.net+bonus.tax);}
    @Test void pendingCreditsSurviveReloadAndDailyRollover(){var l=ledger();Round r=round(l);Reward owed=complete(l,r.quests.getFirst(),0);l=DailyLedger.fromJson(DailyLedger.JSON.toJson(l));l.generate(PLAYER,r.resetAt,catalog(),"CHRONICLES");assertFalse(l.rewards.get(owed.id).paid);assertEquals(owed.net,l.rewards.get(owed.id).net);l.paid(owed.id);l.validate();}
    @Test void latePaymentsCanCompleteAnArchivedDailySet(){var l=ledger();Round old=round(l);for(var q:old.quests)complete(l,q,0);l.generate(PLAYER,old.resetAt,catalog(),"CHRONICLES");for(var q:old.quests)l.paid(q.id);assertNotNull(l.special(PLAYER,old,old.resetAt+100,0));}
    @Test void emeraldFallbackUsesWholeUnitsAndConservesThePublicShare(){var l=ledger();l.settings.emeraldFallback=true;l.settings.bonuses.replaceAll((c,v)->1500);Round r=l.generate(PLAYER,NOW,catalog(),"EMERALD");for(var q:r.quests){assertEquals(0,q.gross%100);Reward reward=complete(l,q,0);assertEquals(0,reward.net%100);assertEquals(0,reward.tax%100);assertEquals(reward.gross,reward.net+reward.tax);}}
    @Test void corruptedDailyTotalsAreRejectedInsteadOfReissuingMoney(){var l=ledger();Round r=round(l);complete(l,r.quests.getFirst(),0);r.grossCompleted++;assertThrows(IllegalArgumentException.class,()->DailyLedger.fromJson(DailyLedger.JSON.toJson(l)));}
    @Test void changedReceiptAmountsCannotBeLoadedAsAValidQuest(){var l=ledger();var r=complete(l,round(l).quests.getFirst(),0);r.gross++;r.net++;assertThrows(IllegalArgumentException.class,()->l.validate());}
    @Test void invalidDistributionPricesAndFiscalCapsAreRejected(){Settings s=new Settings();s.easyCount=Integer.MAX_VALUE;assertThrows(IllegalArgumentException.class,s::validate);s=new Settings();s.dailyCap=10;assertThrows(IllegalArgumentException.class,s::validate);s=new Settings();s.taxBps=2501;assertThrows(IllegalArgumentException.class,s::validate);s=new Settings();s.bonuses.put(Category.MINING,2001);assertThrows(IllegalArgumentException.class,s::validate);}
    @Test void catalogueRejectsUnsupportedValidatorsAndMalformedIds(){assertThrows(IllegalArgumentException.class,()->new Template("invalid","Bad",Category.MINING,Difficulty.EASY,"minecraft:stone",1,-1,1,Set.of(),Set.of(),Set.of(),true,null));assertThrows(IllegalArgumentException.class,()->new Template("test:a","Bad",Category.MINING,Difficulty.EASY,"minecraft:stone",1,-1,1,Set.of(),Set.of(),Set.of(),true,Validation.CONSUME_ITEMS));}
    @Test void placedAndConsumedPositionsCannotBeReused(){var l=ledger();assertTrue(l.mark("minecraft:overworld@12",true));assertFalse(l.mark("minecraft:overworld@12",false));assertTrue(l.mark("minecraft:overworld@13",false));assertFalse(l.mark("minecraft:overworld@13",false));var restored=DailyLedger.fromJson(DailyLedger.JSON.toJson(l));assertFalse(restored.mark("minecraft:overworld@12",false));}
    @Test void administrativeChangesKeepABoundedAttributableAudit(){var l=ledger();for(int i=0;i<1100;i++)l.audit(PLAYER,"tax","rate="+i,NOW+i);assertEquals(1000,l.audit.size());assertEquals(1100,l.revision);assertEquals(PLAYER,l.audit.getFirst().actor());}
}
